draw:
var R = 8.31;
var M = p.mass / 1000.0;
var T = p.temp;
var vrms = Math.sqrt(3 * R * T / M);
var N = Math.round(p.count);

var pad = 26;
var x0 = pad, x1 = W - pad - 96;
var y0 = pad, y1 = H - pad;
var Lx = x1 - x0, Ly = y1 - y0;

ctx.lineWidth = 1.5;
ctx.strokeStyle = C.ink;
ctx.strokeRect(x0, y0, Lx, Ly);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.figure;
ctx.fillText("right wall", x1 + 6, y0 + 14);
ctx.fillText("area A", x1 + 6, y0 + 30);

function fold(u, L) {
  var q = u % (2 * L);
  if (q < 0) { q = q + 2 * L; }
  return q > L ? 2 * L - q : q;
}

var pxPerMs = (Lx * 0.45) / vrms;
var hits = 0;
var i;
for (i = 0; i < N; i++) {
  var a = (i * 2.39996) + 0.37;
  var sp = vrms * (0.55 + 0.9 * ((i * 7 % 11) / 10));
  var vx = sp * Math.cos(a) * pxPerMs;
  var vy = sp * Math.sin(a) * pxPerMs;
  var sx = (i * 37 % 100) / 100 * Lx;
  var sy = (i * 61 % 100) / 100 * Ly;
  var px = x0 + fold(sx + vx * t, Lx);
  var py = y0 + fold(sy + vy * t, Ly);
  var near = (x1 - px) < 6;
  ctx.fillStyle = near ? C.accent : C.figure;
  ctx.beginPath();
  ctx.arc(px, py, near ? 4 : 3, 0, Math.PI * 2);
  ctx.fill();
  if (near) { hits++; }
  if (i === 0) {
    ctx.strokeStyle = C.accent;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.lineTo(px + vx * 0.09, py + vy * 0.09);
    ctx.stroke();
  }
}

ctx.fillStyle = C.ink;
ctx.fillText("v_rms = " + Math.round(vrms) + " m/s", x1 + 6, y1 - 24);
ctx.fillStyle = C.faint;
ctx.fillText("T = " + Math.round(T) + " K", x1 + 6, y1 - 8);

out.note = "v_rms = " + vrms.toFixed(0) + " m/s at " + T.toFixed(0) + " K for M = " + p.mass.toFixed(0) + " g/mol; " + hits + " of " + N + " molecules touching the right wall right now";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var wx = W * 0.72;
var mid = H * 0.42;

ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(wx, 16); ctx.lineTo(wx, H - 30); ctx.stroke();
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var k;
for (k = 0; k < 12; k++) {
  var yy = 16 + k * (H - 46) / 12;
  ctx.beginPath(); ctx.moveTo(wx, yy); ctx.lineTo(wx + 10, yy + 8); ctx.stroke();
}
ctx.fillStyle = C.figure;
ctx.fillText("wall, area A", wx + 14, 26);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(wx - 150, mid); ctx.lineTo(wx - 22, mid); ctx.stroke();
ctx.beginPath();
ctx.moveTo(wx - 22, mid); ctx.lineTo(wx - 32, mid - 5); ctx.lineTo(wx - 32, mid + 5);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("before:  +m v_x", wx - 150, mid - 10);

var mid2 = H * 0.72;
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(wx - 22, mid2); ctx.lineTo(wx - 150, mid2); ctx.stroke();
ctx.beginPath();
ctx.moveTo(wx - 150, mid2); ctx.lineTo(wx - 140, mid2 - 5); ctx.lineTo(wx - 140, mid2 + 5);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("after:  - m v_x", wx - 150, mid2 - 10);
ctx.fillStyle = C.accent;
ctx.fillText("change of 2 m v_x, so the wall gets 2 m v_x", 16, H - 10);

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.strokeRect(wx - 150, 16, 150, H - 46);
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("only molecules inside this slab,", 16, H * 0.16);
ctx.fillText("of length v_x times dt, can reach", 16, H * 0.16 + 14);
ctx.fillText("the wall in time dt", 16, H * 0.16 + 28);

var R = 8.31;
var M = p.mass / 1000.0;
var T = p.temp;
var vrms = Math.sqrt(3 * R * T / M);
var vbar = Math.sqrt(8 * R * T / (Math.PI * M));
var vp = Math.sqrt(2 * R * T / M);

var pad = 34;
var x0 = pad, x1 = W - 14, y0 = 14, y1 = H - 28;
var vmax = 3000;
var X = function (v) { return x0 + (v / vmax) * (x1 - x0); };

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, y1); ctx.lineTo(x1, y1); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, y1); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.figure;
ctx.fillText("speed v  (m/s)", (x0 + x1) / 2 - 40, H - 8);
ctx.save();
ctx.translate(12, (y0 + y1) / 2 + 30);
ctx.rotate(-Math.PI / 2);
ctx.fillText("fraction per unit speed", 0, 0);
ctx.restore();
var g;
for (g = 0; g <= 3; g++) {
  var vv = g * 1000;
  ctx.fillStyle = C.faint;
  ctx.fillText(String(vv), X(vv) - 10, y1 + 15);
}

var a = M / (2 * R * T);
var f = function (v) { return v * v * Math.exp(-a * v * v); };
var peak = f(vp);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var s;
for (s = 0; s <= 240; s++) {
  var v = s * vmax / 240;
  var yy = y1 - (f(v) / peak) * (y1 - y0) * 0.92;
  if (s === 0) { ctx.moveTo(X(v), yy); } else { ctx.lineTo(X(v), yy); }
}
ctx.stroke();

function mark(v, name, off) {
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(X(v), y1); ctx.lineTo(X(v), y0 + off); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.fillText(name, X(v) + 3, y0 + off + 10);
}
mark(vp, "most likely", 4);
mark(vbar, "mean", 24);
mark(vrms, "rms", 44);

out.note = "most likely " + vp.toFixed(0) + " m/s, mean " + vbar.toFixed(0) + " m/s, rms " + vrms.toFixed(0) + " m/s  (rms is always the largest of the three)";

var d = p.diam * 1e-10;
var n = p.dens * 1e25;
var lam = 1 / (Math.SQRT2 * Math.PI * d * d * n);
var vbar = p.speed;
var rate = vbar / lam;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var pad = 22;
var x0 = pad, x1 = W - pad, y0 = 20, y1 = H - 34;
var yc = (y0 + y1) / 2;

var pxPerLam = (x1 - x0) / 5.0;
var tube = Math.max(6, Math.min(26, pxPerLam * 0.22));

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(x0, yc - tube); ctx.lineTo(x1, yc - tube); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, yc + tube); ctx.lineTo(x1, yc + tube); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("swept tube of cross-section pi d squared", x0, y0 - 6);

ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(x0, yc); ctx.lineTo(x1, yc); ctx.stroke();

var i;
for (i = 1; i <= 5; i++) {
  var hx = x0 + i * pxPerLam;
  if (hx > x1) { break; }
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(hx, yc, 4, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(hx, yc - tube); ctx.lineTo(hx, yc + tube); ctx.stroke();
}

var travel = (t * 0.9) % 5;
var mx = x0 + travel * pxPerLam;
if (mx < x1) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(mx, yc, 5, 0, Math.PI * 2); ctx.fill();
}

ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
var ay = y1 + 4;
ctx.beginPath(); ctx.moveTo(x0, ay); ctx.lineTo(x0 + pxPerLam, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, ay - 4); ctx.lineTo(x0, ay + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0 + pxPerLam, ay - 4); ctx.lineTo(x0 + pxPerLam, ay + 4); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("one mean free path", x0 + 6, ay + 18);

out.note = "mean free path " + lam.toExponential(2) + " m, and at " + vbar.toFixed(0) + " m/s that is " + rate.toExponential(2) + " collisions per second";
